-- =============================================
-- 校园心理健康服务平台 - 数据库初始化脚本
-- 数据库: mental_health_server
-- MySQL 8.0, 端口 3306
-- 默认密码 123456 的 MD5: e10adc3949ba59abbe56e057f20f883e
--
-- 同步方式: python sql/sync_init.py  （DDL + 数据，重跑本文件可恢复当前库）
-- 开发监听: python sql/watch_sync.py
-- 仅同步结构: python sql/sync_init.py --schema-only
-- =============================================

CREATE DATABASE IF NOT EXISTS mental_health_server
  DEFAULT CHARACTER SET utf8mb4
  DEFAULT COLLATE utf8mb4_unicode_ci;

USE mental_health_server;
-- ----------------------------
-- 删除旧表（按外键依赖顺序）
-- ----------------------------
DROP TABLE IF EXISTS knowledge_chunks;
DROP TABLE IF EXISTS notifications;
DROP TABLE IF EXISTS tree_hole_replies;
DROP TABLE IF EXISTS tree_hole_posts;
DROP TABLE IF EXISTS relaxation_favorites;
DROP TABLE IF EXISTS relaxation_likes;
DROP TABLE IF EXISTS relaxation_audios;
DROP TABLE IF EXISTS ai_chat_messages;
DROP TABLE IF EXISTS ai_chat_sessions;
DROP TABLE IF EXISTS consultation_messages;
DROP TABLE IF EXISTS consultations;
DROP TABLE IF EXISTS mood_diaries;
DROP TABLE IF EXISTS scale_answers;
DROP TABLE IF EXISTS scale_records;
DROP TABLE IF EXISTS scale_questions;
DROP TABLE IF EXISTS scales;
DROP TABLE IF EXISTS appointments;
DROP TABLE IF EXISTS article_favorites;
DROP TABLE IF EXISTS article_likes;
DROP TABLE IF EXISTS articles;
DROP TABLE IF EXISTS announcements;
DROP TABLE IF EXISTS counselor_profiles;
DROP TABLE IF EXISTS student_registry;
DROP TABLE IF EXISTS users;

-- ----------------------------
-- 用户表
-- ----------------------------
CREATE TABLE users (
    id INT NOT NULL AUTO_INCREMENT COMMENT '用户ID',
    username VARCHAR(50) NOT NULL COMMENT '用户名',
    password VARCHAR(64) NOT NULL COMMENT '密码(MD5加密)',
    real_name VARCHAR(50) NOT NULL COMMENT '真实姓名',
    student_no VARCHAR(20) DEFAULT NULL COMMENT '学号(学生)',
    nickname VARCHAR(50) DEFAULT NULL COMMENT '昵称',
    role ENUM('student','counselor','admin') NOT NULL DEFAULT 'student' COMMENT '角色',
    phone VARCHAR(20) DEFAULT NULL COMMENT '手机号',
    email VARCHAR(100) DEFAULT NULL COMMENT '邮箱',
    security_question VARCHAR(200) DEFAULT NULL COMMENT '找回密码安全问题',
    security_answer VARCHAR(64) DEFAULT NULL COMMENT '安全问题答案(MD5)',
    gender TINYINT DEFAULT '0' COMMENT '性别: 0未知 1男 2女',
    avatar VARCHAR(255) DEFAULT NULL COMMENT '头像URL',
    status TINYINT DEFAULT '1' COMMENT '状态: 0禁用 1正常',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (id),
    UNIQUE KEY username (username),
    UNIQUE KEY student_no (student_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';


-- ----------------------------
-- 学籍库（全校学生名册，用于注册校验）
-- ----------------------------
CREATE TABLE student_registry (
    id INT NOT NULL AUTO_INCREMENT,
    student_no VARCHAR(20) NOT NULL,
    real_name VARCHAR(50) NOT NULL,
    gender TINYINT DEFAULT '0',
    department VARCHAR(100) DEFAULT NULL,
    class_name VARCHAR(50) DEFAULT NULL,
    is_registered TINYINT DEFAULT '0',
    user_id INT DEFAULT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    registered_at DATETIME DEFAULT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY student_no (student_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- 咨询师档案表
-- ----------------------------
CREATE TABLE counselor_profiles (
    id INT NOT NULL AUTO_INCREMENT COMMENT '档案ID',
    user_id INT NOT NULL COMMENT '关联用户ID',
    title VARCHAR(50) DEFAULT NULL COMMENT '职称',
    specialty VARCHAR(200) DEFAULT NULL COMMENT '擅长领域',
    introduction TEXT COMMENT '个人简介',
    available_days VARCHAR(100) DEFAULT '1,2,3,4,5' COMMENT '可预约星期(1-7)',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    detail_bio TEXT COMMENT '详细介绍',
    PRIMARY KEY (id),
    UNIQUE KEY user_id (user_id),
    CONSTRAINT counselor_profiles_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='咨询师档案表';


-- ----------------------------
-- 公告表
-- ----------------------------
CREATE TABLE announcements (
    id INT NOT NULL AUTO_INCREMENT COMMENT '公告ID',
    title VARCHAR(200) NOT NULL COMMENT '公告标题',
    content TEXT NOT NULL COMMENT '公告内容',
    publisher_id INT NOT NULL COMMENT '发布者ID',
    status TINYINT DEFAULT '1' COMMENT '状态: 0下架 1发布',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    PRIMARY KEY (id),
    KEY publisher_id (publisher_id),
    CONSTRAINT announcements_ibfk_1 FOREIGN KEY (publisher_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='公告表';


-- ----------------------------
-- 心理文章表
-- ----------------------------
CREATE TABLE articles (
    id INT NOT NULL AUTO_INCREMENT COMMENT '文章ID',
    title VARCHAR(200) NOT NULL COMMENT '文章标题',
    content TEXT NOT NULL COMMENT '文章内容',
    category VARCHAR(50) DEFAULT '心理健康' COMMENT '文章分类',
    author_id INT NOT NULL COMMENT '作者ID',
    cover_image VARCHAR(255) DEFAULT NULL COMMENT '封面图片',
    view_count INT DEFAULT '0' COMMENT '浏览次数',
    like_count INT DEFAULT '0' COMMENT '点赞数',
    status TINYINT DEFAULT '1' COMMENT '状态: 0草稿 1发布',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (id),
    KEY author_id (author_id),
    CONSTRAINT articles_ibfk_1 FOREIGN KEY (author_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='心理文章表';


-- ----------------------------
-- 文章点赞表
-- ----------------------------
CREATE TABLE article_likes (
    id INT NOT NULL AUTO_INCREMENT COMMENT '点赞ID',
    user_id INT NOT NULL COMMENT '用户ID',
    article_id INT NOT NULL COMMENT '文章ID',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '点赞时间',
    PRIMARY KEY (id),
    UNIQUE KEY uk_like (user_id,article_id),
    KEY article_id (article_id),
    CONSTRAINT article_likes_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT article_likes_ibfk_2 FOREIGN KEY (article_id) REFERENCES articles (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='文章点赞表';


-- ----------------------------
-- 文章收藏表
-- ----------------------------
CREATE TABLE article_favorites (
    id INT NOT NULL AUTO_INCREMENT COMMENT '收藏ID',
    user_id INT NOT NULL COMMENT '用户ID',
    article_id INT NOT NULL COMMENT '文章ID',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
    PRIMARY KEY (id),
    UNIQUE KEY uk_favorite (user_id,article_id),
    KEY article_id (article_id),
    CONSTRAINT article_favorites_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT article_favorites_ibfk_2 FOREIGN KEY (article_id) REFERENCES articles (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='文章收藏表';


-- ----------------------------
-- 咨询预约表
-- ----------------------------
CREATE TABLE appointments (
    id INT NOT NULL AUTO_INCREMENT COMMENT '预约ID',
    student_id INT NOT NULL COMMENT '学生ID',
    student_real_name VARCHAR(50) DEFAULT NULL COMMENT '预约时填写的真实姓名',
    counselor_id INT NOT NULL COMMENT '咨询师ID',
    appointment_date DATE NOT NULL COMMENT '预约日期',
    time_slot VARCHAR(20) NOT NULL COMMENT '时间段',
    reason TEXT COMMENT '预约原因',
    status ENUM('pending','confirmed','completed','cancelled') DEFAULT 'pending' COMMENT '状态',
    remark TEXT COMMENT '咨询师备注',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (id),
    KEY student_id (student_id),
    KEY counselor_id (counselor_id),
    CONSTRAINT appointments_ibfk_1 FOREIGN KEY (student_id) REFERENCES users (id),
    CONSTRAINT appointments_ibfk_2 FOREIGN KEY (counselor_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='咨询预约表';


-- ----------------------------
-- 心理量表表
-- ----------------------------
CREATE TABLE scales (
    id INT NOT NULL AUTO_INCREMENT COMMENT '量表ID',
    name VARCHAR(100) NOT NULL COMMENT '量表名称',
    description TEXT COMMENT '量表描述',
    question_count INT DEFAULT '0' COMMENT '题目数量',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='心理量表表';


-- ----------------------------
-- 量表题目表
-- ----------------------------
CREATE TABLE scale_questions (
    id INT NOT NULL AUTO_INCREMENT COMMENT '题目ID',
    scale_id INT NOT NULL COMMENT '量表ID',
    question_text VARCHAR(500) NOT NULL COMMENT '题目内容',
    options_json JSON NOT NULL COMMENT '选项JSON',
    sort_order INT DEFAULT '0' COMMENT '排序',
    PRIMARY KEY (id),
    KEY scale_id (scale_id),
    CONSTRAINT scale_questions_ibfk_1 FOREIGN KEY (scale_id) REFERENCES scales (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='量表题目表';


-- ----------------------------
-- 量表测评记录表
-- ----------------------------
CREATE TABLE scale_records (
    id INT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
    user_id INT NOT NULL COMMENT '用户ID',
    scale_id INT NOT NULL COMMENT '量表ID',
    total_score INT DEFAULT '0' COMMENT '总分',
    result_level VARCHAR(50) DEFAULT NULL COMMENT '结果等级',
    result_desc TEXT COMMENT '结果描述',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '测评时间',
    result_analysis TEXT COMMENT '具体分析',
    result_advice TEXT COMMENT '改善建议',
    PRIMARY KEY (id),
    KEY user_id (user_id),
    KEY scale_id (scale_id),
    CONSTRAINT scale_records_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT scale_records_ibfk_2 FOREIGN KEY (scale_id) REFERENCES scales (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='量表测评记录表';


-- ----------------------------
-- 量表答题详情表
-- ----------------------------
CREATE TABLE scale_answers (
    id INT NOT NULL AUTO_INCREMENT COMMENT '答案ID',
    record_id INT NOT NULL COMMENT '记录ID',
    question_id INT NOT NULL COMMENT '题目ID',
    answer_score INT DEFAULT '0' COMMENT '所选分值',
    PRIMARY KEY (id),
    KEY record_id (record_id),
    KEY question_id (question_id),
    CONSTRAINT scale_answers_ibfk_1 FOREIGN KEY (record_id) REFERENCES scale_records (id) ON DELETE CASCADE,
    CONSTRAINT scale_answers_ibfk_2 FOREIGN KEY (question_id) REFERENCES scale_questions (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='量表答题详情表';


-- ----------------------------
-- 心情日记表
-- ----------------------------
CREATE TABLE mood_diaries (
    id INT NOT NULL AUTO_INCREMENT COMMENT '日记ID',
    user_id INT NOT NULL COMMENT '用户ID',
    mood_level TINYINT NOT NULL COMMENT '心情等级(1-5)',
    content TEXT COMMENT '日记内容',
    tags VARCHAR(200) DEFAULT NULL COMMENT '标签',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '记录时间',
    media_url VARCHAR(500) DEFAULT NULL COMMENT '媒体文件地址',
    media_type ENUM('image','video') DEFAULT NULL COMMENT '媒体类型',
    media_list JSON DEFAULT NULL COMMENT '多媒体列表',
    PRIMARY KEY (id),
    KEY user_id (user_id),
    CONSTRAINT mood_diaries_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='心情日记表';


-- ----------------------------
-- 在线咨询会话表
-- ----------------------------
CREATE TABLE consultations (
    id INT NOT NULL AUTO_INCREMENT COMMENT '会话ID',
    student_id INT NOT NULL COMMENT '学生ID',
    counselor_id INT NOT NULL COMMENT '咨询师ID',
    title VARCHAR(200) DEFAULT '在线咨询' COMMENT '会话标题',
    is_anonymous TINYINT DEFAULT '0' COMMENT '学生是否匿名咨询',
    status ENUM('active','closed') DEFAULT 'active' COMMENT '状态',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (id),
    KEY student_id (student_id),
    KEY counselor_id (counselor_id),
    CONSTRAINT consultations_ibfk_1 FOREIGN KEY (student_id) REFERENCES users (id),
    CONSTRAINT consultations_ibfk_2 FOREIGN KEY (counselor_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='在线咨询会话表';


-- ----------------------------
-- 咨询消息表
-- ----------------------------
CREATE TABLE consultation_messages (
    id INT NOT NULL AUTO_INCREMENT COMMENT '消息ID',
    consultation_id INT NOT NULL COMMENT '会话ID',
    sender_id INT NOT NULL COMMENT '发送者ID',
    content TEXT NOT NULL COMMENT '消息内容',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '发送时间',
    PRIMARY KEY (id),
    KEY consultation_id (consultation_id),
    KEY sender_id (sender_id),
    CONSTRAINT consultation_messages_ibfk_1 FOREIGN KEY (consultation_id) REFERENCES consultations (id) ON DELETE CASCADE,
    CONSTRAINT consultation_messages_ibfk_2 FOREIGN KEY (sender_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='咨询消息表';


-- ----------------------------
-- AI心理助手会话表
-- ----------------------------
CREATE TABLE ai_chat_sessions (
    id INT NOT NULL AUTO_INCREMENT COMMENT '会话ID',
    user_id INT NOT NULL COMMENT '用户ID',
    title VARCHAR(200) DEFAULT 'AI心理助手' COMMENT '会话标题',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (id),
    KEY user_id (user_id),
    CONSTRAINT ai_chat_sessions_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI心理助手会话表';


-- ----------------------------
-- AI心理助手消息表
-- ----------------------------
CREATE TABLE ai_chat_messages (
    id INT NOT NULL AUTO_INCREMENT COMMENT '消息ID',
    session_id INT NOT NULL COMMENT '会话ID',
    role ENUM('user','assistant') NOT NULL COMMENT '角色',
    content TEXT NOT NULL COMMENT '消息内容',
    rag_sources JSON DEFAULT NULL COMMENT 'RAG检索来源',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '发送时间',
    PRIMARY KEY (id),
    KEY session_id (session_id),
    CONSTRAINT ai_chat_messages_ibfk_1 FOREIGN KEY (session_id) REFERENCES ai_chat_sessions (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI心理助手消息表';


-- ----------------------------
-- 放松训练音频表
-- ----------------------------
CREATE TABLE relaxation_audios (
    id INT NOT NULL AUTO_INCREMENT COMMENT '音频ID',
    title VARCHAR(100) NOT NULL COMMENT '标题',
    description TEXT COMMENT '描述',
    category VARCHAR(50) DEFAULT '放松训练' COMMENT '分类',
    media_type ENUM('audio','video') DEFAULT 'audio' COMMENT '媒体类型',
    audio_url VARCHAR(500) NOT NULL COMMENT '媒体文件地址(音频或视频)',
    duration VARCHAR(20) DEFAULT NULL COMMENT '时长',
    cover_icon VARCHAR(10) DEFAULT 0xF09F8EB5 COMMENT '封面图标',
    status TINYINT DEFAULT '1' COMMENT '状态',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    like_count INT DEFAULT '0' COMMENT '点赞数',
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='放松训练音频表';


-- ----------------------------
-- 放松训练点赞表
-- ----------------------------
CREATE TABLE relaxation_likes (
    id INT NOT NULL AUTO_INCREMENT,
    user_id INT NOT NULL,
    audio_id INT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_relax_like (user_id,audio_id),
    KEY audio_id (audio_id),
    CONSTRAINT relaxation_likes_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT relaxation_likes_ibfk_2 FOREIGN KEY (audio_id) REFERENCES relaxation_audios (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- 放松训练收藏表
-- ----------------------------
CREATE TABLE relaxation_favorites (
    id INT NOT NULL AUTO_INCREMENT,
    user_id INT NOT NULL,
    audio_id INT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_relax_fav (user_id,audio_id),
    KEY audio_id (audio_id),
    CONSTRAINT relaxation_favorites_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT relaxation_favorites_ibfk_2 FOREIGN KEY (audio_id) REFERENCES relaxation_audios (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- 栖心树洞帖子表
-- ----------------------------
CREATE TABLE tree_hole_posts (
    id INT NOT NULL AUTO_INCREMENT COMMENT '帖子ID',
    user_id INT NOT NULL COMMENT '发布者ID(匿名不对外展示)',
    content TEXT NOT NULL COMMENT '留言内容',
    is_anonymous TINYINT DEFAULT '1' COMMENT '是否匿名:1是 0否',
    status TINYINT DEFAULT '1' COMMENT '状态:0隐藏 1显示',
    reply_count INT DEFAULT '0' COMMENT '回复数',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
    media_url VARCHAR(500) DEFAULT NULL COMMENT '媒体文件地址',
    media_type ENUM('image','video') DEFAULT NULL COMMENT '媒体类型',
    media_list JSON DEFAULT NULL COMMENT '多媒体列表',
    PRIMARY KEY (id),
    KEY user_id (user_id),
    CONSTRAINT tree_hole_posts_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='匿名树洞帖子表';


-- ----------------------------
-- 树洞回复表
-- ----------------------------
CREATE TABLE tree_hole_replies (
    id INT NOT NULL AUTO_INCREMENT COMMENT '回复ID',
    post_id INT NOT NULL COMMENT '帖子ID',
    replier_id INT NOT NULL COMMENT '回复者ID',
    content TEXT NOT NULL COMMENT '回复内容',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '回复时间',
    media_url VARCHAR(500) DEFAULT NULL COMMENT '媒体文件地址',
    media_type ENUM('image','video') DEFAULT NULL COMMENT '媒体类型',
    media_list JSON DEFAULT NULL COMMENT '多媒体列表',
    PRIMARY KEY (id),
    KEY post_id (post_id),
    KEY replier_id (replier_id),
    CONSTRAINT tree_hole_replies_ibfk_1 FOREIGN KEY (post_id) REFERENCES tree_hole_posts (id) ON DELETE CASCADE,
    CONSTRAINT tree_hole_replies_ibfk_2 FOREIGN KEY (replier_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='树洞回复表';


-- ----------------------------
-- 消息通知表
-- ----------------------------
CREATE TABLE notifications (
    id INT NOT NULL AUTO_INCREMENT COMMENT '通知ID',
    user_id INT NOT NULL COMMENT '接收用户ID',
    title VARCHAR(200) NOT NULL COMMENT '通知标题',
    content TEXT COMMENT '通知内容',
    type VARCHAR(50) DEFAULT 'system' COMMENT '类型:system/appointment/consultation/tree_hole/scale',
    related_id INT DEFAULT NULL COMMENT '关联业务ID',
    is_read TINYINT DEFAULT '0' COMMENT '是否已读:0未读 1已读',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    PRIMARY KEY (id),
    KEY user_id (user_id),
    CONSTRAINT notifications_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='消息通知表';


-- ----------------------------
-- RAG 知识库文本块（向量嵌入存 JSON）
-- ----------------------------
CREATE TABLE knowledge_chunks (
    id INT NOT NULL AUTO_INCREMENT COMMENT '知识块ID',
    source_type VARCHAR(50) NOT NULL COMMENT '来源类型：scale_overview/scale_questions/scoring_rule',
    source_id INT DEFAULT NULL COMMENT '来源业务ID（如量表ID）',
    chunk_index INT DEFAULT '0' COMMENT '同一来源内的分片序号',
    title VARCHAR(200) DEFAULT NULL COMMENT '标题',
    content TEXT NOT NULL COMMENT '知识正文',
    embedding LONGTEXT NOT NULL COMMENT '嵌入向量 JSON 数组',
    metadata JSON DEFAULT NULL COMMENT '扩展元数据',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (id),
    KEY idx_source (source_type,source_id),
    KEY idx_chunk (source_type,source_id,chunk_index)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='RAG知识库文本块';

