-- 咨询师档案
INSERT INTO counselor_profiles (id, user_id, title, specialty, introduction, available_days, created_at, detail_bio) VALUES
(1, 2, '国家二级心理咨询师', '情绪管理,学业压力,人际关系', '从事心理咨询工作10年，擅长帮助大学生应对学业与情感困扰。', '1,2,3,4,5', '2026-07-11 15:45:28', '张心理老师拥有心理学硕士学位与国家二级心理咨询师资质，累计个体咨询时长超过3000小时。擅长运用认知行为疗法（CBT）与正念减压技术，帮助大学生处理学业压力、考试焦虑、人际冲突与情感困扰。曾多次面向全校开展心理健康讲座与团体辅导，深受学生信赖。咨询风格温暖务实，注重帮助学生发掘自身资源与应对力量。'),
(2, 3, '心理学硕士', '焦虑抑郁,自我认知,职业规划', '专注于青少年心理健康，善于运用认知行为疗法帮助学生成长。', '1,2,3,4,5', '2026-07-11 15:45:28', '李咨询老师毕业于重点高校心理学专业，持有心理学硕士学位。专注于大学生焦虑、抑郁情绪的识别与干预，在自我认知提升与职业生涯规划方面有丰富经验。擅长通过结构化访谈与心理测评工具帮助学生厘清困扰来源，制定切实可行的改变计划。曾参与多项校园心理健康项目，对当代大学生心理特点有深入理解。'),
(3, 4, '国家三级心理咨询师', '恋爱情感,家庭关系,自我成长', '温柔耐心，擅长倾听与陪伴，帮助学生在亲密关系与家庭沟通中找到平衡。', '1,2,3,4,5', '2026-07-11 15:45:28', '王静心老师是国家三级心理咨询师，长期专注于大学生恋爱情感、家庭关系与自我成长议题。咨询中强调无条件积极关注与深度倾听，善于在安全、包容的氛围中陪伴学生探索内心。擅长处理失恋创伤、异地恋困扰、亲子沟通障碍等问题，帮助学生在关系中找到自我边界与情感平衡。'),
(4, 5, '临床心理学硕士', '社交焦虑,完美主义,适应障碍', '熟悉团体辅导与个体咨询，帮助新生快速适应大学生活，缓解社交与学业压力。', '1,2,3,4,5', '2026-07-11 15:45:28', '陈阳光老师拥有临床心理学硕士学位，擅长社交焦虑、完美主义与大学适应障碍的咨询辅导。对新生适应、社团人际、公众表达恐惧等问题有深入研究，善于结合团体活动与个体咨询帮助学生逐步突破舒适区。咨询风格积极阳光，注重实用技巧训练与行为改变。'),
(5, 6, '注册心理师', '危机干预,创伤疗愈,生涯困惑', '具有危机干预经验，擅长支持经历挫折或重大变化的同学重建信心与方向。', '1,2,3,4,5', '2026-07-11 15:45:28', '刘思远老师是注册心理师，具有系统的危机干预与创伤疗愈培训背景。擅长陪伴经历学业挫折、人际创伤、家庭变故等重大生活事件的学生，帮助其重建安全感与自我价值感。在生涯困惑与方向探索方面，善于引导学生从兴趣、能力与价值观出发，找到属于自己的成长路径。');

