-- 测评记录
INSERT INTO scale_records (id, user_id, scale_id, total_score, result_level, result_desc, created_at, result_analysis, result_advice) VALUES
(1, 7, 1, 8, '轻度抑郁', '您的得分提示可能存在轻度抑郁症状，建议关注自身情绪变化，必要时寻求心理咨询。', '2026-07-11 15:45:29', NULL, NULL),
(2, 8, 2, 5, '轻度焦虑', '您的得分提示可能存在轻度焦虑症状，可尝试放松训练和规律运动来缓解。', '2026-07-11 15:45:29', NULL, NULL),
(3, 7, 3, 7, '压力适中', '您感受到适度的压力，注意劳逸结合。', '2026-07-11 16:23:19', '测评表明您处于适度压力区间。适度压力有助于激发动力，但也需要关注是否出现疲劳累积。若长期维持高负荷而休息不足，压力可能逐步升高。', '1. 使用番茄工作法，劳逸结合，避免连续长时间学习；\n2. 每周安排固定放松时间，如运动、冥想或户外活动；\n3. 学会说「不」，合理分配精力，避免过度承诺；\n4. 关注睡眠与饮食，它们是压力恢复的关键；\n5. 感到吃力时，可与同学倾诉或预约咨询。'),
(4, 10, 3, 3, '压力较低', '您当前的压力水平较低，状态良好。', '2026-07-13 09:07:10', '测评显示您目前承受的压力较小，能够较好地平衡学习、生活与休息。身心处于相对松弛的状态，具备较好的抗压基础和恢复能力。', '1. 保持现有节奏，注意在忙碌期来临前做好时间规划；\n2. 培养1–2项可持续的减压爱好；\n3. 维持与支持性朋友、家人的联系；\n4. 可定期自评压力水平，做到早觉察、早调节。'),
(5, 10, 2, 7, '轻度焦虑', '您可能存在轻度焦虑，可尝试深呼吸、运动等方式缓解。', '2026-07-20 09:41:39', '测评提示轻度焦虑，您可能时常感到紧张、担忧或对某些事情过度思虑，但尚能完成日常任务。这种焦虑多与学业、社交或未来不确定性有关，通过自我调节和适度支持通常可以改善。', '1. 练习腹式呼吸、渐进式肌肉放松等技巧（见「放松训练」）；\n2. 每天安排30分钟有氧运动，有助于降低焦虑激素水平；\n3. 限制咖啡因摄入，尤其在下午和晚上；\n4. 将担忧写下来，区分「可解决的问题」与「无法控制的担忧」；\n5. 若焦虑持续加重，可考虑心理咨询。');

