(2, '正念身体扫描', '15分钟身体扫描冥想引导，从头顶到脚尖依次放松，适合睡前或焦虑时使用。', '正念冥想', 'video', '/static/media/relaxation/body_scan.m4v', '15:00', '🧘', 1, '2026-07-11 15:45:29', 0),
(3, '自然白噪音 · 再次相遇在夏天', '治愈纯音乐，轻柔旋律如夏日微风，帮助舒缓情绪、放松身心。', '音乐疗愈', 'audio', '/static/media/relaxation/nature_summer.mp3', '6:30', '🌿', 1, '2026-07-11 15:45:29', 0),
(4, '自然白噪音 · 溪畔谧语', '溪水潺潺、鸟鸣悠扬的自然疗愈音，适合冥想、阅读与助眠。', '音乐疗愈', 'audio', '/static/media/relaxation/nature_stream.mp3', '6:45', '🌧️', 1, '2026-07-11 15:45:29', 0),
(5, '渐进式肌肉放松', '跟随视频依次收紧再放松全身肌肉群，释放躯体紧张感。', '肌肉放松', 'video', '/static/media/relaxation/muscle.mp4', '12:00', '💆', 1, '2026-07-11 15:45:29', 0),
(6, '舒缓钢琴曲', '轻柔的钢琴旋律，适合学习间隙或情绪低落时聆听。', '音乐疗愈', 'audio', '/static/media/relaxation/piano.mp3', '6:00', '🎹', 1, '2026-07-11 15:45:29', 0),
(7, '考前减压冥想', '考前专属正念冥想引导，帮助缓解考试焦虑，稳定情绪、专注当下。', '正念冥想', 'video', '/static/media/relaxation/exam_meditation.mp4', '10:00', '🧘', 1, '2026-07-11 15:45:29', 0),
